import ast, copy, hashlib, itertools, json, math, py_compile
from pathlib import Path
root=Path('/workspace');p=json.loads((root/'proposal.json').read_text());r=json.load(open('/tmp/research_runtime.json'))
def validate(v,s,path='study'):
 typ=s.get('type')
 checks={'object':lambda:isinstance(v,dict),'array':lambda:isinstance(v,list),'string':lambda:isinstance(v,str),'boolean':lambda:isinstance(v,bool),'integer':lambda:isinstance(v,int) and not isinstance(v,bool),'number':lambda:isinstance(v,(int,float)) and not isinstance(v,bool)}
 if typ: assert checks[typ](),(path,'type',typ)
 if 'enum' in s:assert v in s['enum'],(path,'enum')
 if 'const' in s:assert v==s['const'],(path,'const')
 if isinstance(v,str):assert len(v)>=s.get('minLength',0),(path,'minLength')
 if isinstance(v,list):
  assert len(v)>=s.get('minItems',0),(path,'minItems')
  for i,x in enumerate(v):validate(x,s.get('items',{}),path+'.'+str(i))
 if isinstance(v,dict):
  assert set(s.get('required',[]))<=v.keys(),(path,'required')
  props=s.get('properties',{})
  if s.get('additionalProperties') is False:assert set(v)<=set(props),(path,'extra')
  for k,x in v.items():
   if k in props:validate(x,props[k],path+'.'+k)
validate(p['study'],r['study_schema'])
assert p['study']['protocol_ref']==r['required_study_protocol_ref']
allowed=set(r['context']['allowed_observation_ids'])
assert set(p['study']['evidence_refs'])<=allowed
assert p['parent_trial'] in allowed
assert 1<=len(p['variants'])<=4
assert len({v['file'] for v in p['variants']})==len(p['variants'])
assert len({v['name'] for v in p['variants']})==len(p['variants'])
assert any(v['role']=='candidate' for v in p['variants'])
orig=ast.parse(Path('/tmp/candidate_start.py').read_text())
def cls(t):return next(n for n in t.body if isinstance(n,ast.ClassDef) and n.name=='Model')
def methods(t):return {n.name:ast.dump(n,include_attributes=False) for n in cls(t).body if isinstance(n,ast.FunctionDef)}
om=methods(orig)
def constructors(t):
 return [ast.dump(n,include_attributes=False) for n in ast.walk(t) if isinstance(n,ast.Call) and ((isinstance(n.func,ast.Attribute) and isinstance(n.func.value,ast.Name) and n.func.value.id=='nn') or isinstance(n.func,ast.Name) and n.func.id in ('Dice','FeatureEmbeddingDict'))]
original_constructors=constructors(orig)
normalized=[];digests={}
for v in p['variants']:
 assert v['file']==Path(v['file']).name and v['file'].endswith('.py')
 path=root/v['file'];py_compile.compile(str(path),doraise=True,cfile='/tmp/'+v['file']+'c')
 t=ast.parse(path.read_text())
 cfg=next(n for n in t.body if isinstance(n,ast.Assign) and any(isinstance(x,ast.Name) and x.id=='CONFIG' for x in n.targets))
 assert ast.literal_eval(cfg.value)==v['config']
 init=next(n for n in cls(t).body if isinstance(n,ast.FunctionDef) and n.name=='__init__')
 defaults={a.arg:ast.literal_eval(d) for a,d in zip(init.args.args[-len(init.args.defaults):],init.args.defaults)}
 for k,value in v['config'].items():
  expected=defaults[k]
  assert value==expected or (isinstance(value,list) and isinstance(expected,tuple) and value==list(expected)),(v['name'],k)
 assert constructors(t)==original_constructors,(v['name'],'learned constructors changed')
 mm=methods(t)
 for name,value in om.items():
  if name not in ('__init__','_context_history_correction'):assert mm[name]==value,(v['name'],name)
 assert set(mm)==set(om)|{'_block_pair_indices','_paired_block_summary'}
 for n in ast.walk(t):
  if isinstance(n,(ast.Import,ast.ImportFrom)):
   names=[x.name.split('.')[0] for x in n.names] if isinstance(n,ast.Import) else [n.module.split('.')[0]]
   assert all(x in {'torch','numpy','math','typing','copy','functools','collections','itertools','dataclasses','contextlib','unirank','model_zoo'} for x in names)
  if isinstance(n,ast.Call) and isinstance(n.func,ast.Name):assert n.func.id not in {'open','exec','eval','compile','__import__'}
 norm=copy.deepcopy(t)
 for n in norm.body:
  if isinstance(n,ast.Assign) and any(isinstance(x,ast.Name) and x.id=='CONFIG' for x in n.targets):n.value=ast.Dict(keys=[],values=[])
 init=next(n for n in cls(norm).body if isinstance(n,ast.FunctionDef) and n.name=='__init__')
 for a,i in zip(init.args.args[-len(init.args.defaults):],range(len(init.args.defaults))):
  if a.arg in ('block_pairing','block_aux_adapter_context_grad'):init.args.defaults[i]=ast.Constant(value=None)
 normalized.append(ast.dump(norm,include_attributes=False))
 digests[v['file']]=hashlib.sha256(path.read_bytes()).hexdigest()
assert len(set(normalized))==1,'undeclared between-cell source difference'
# Independent scalar emulation of rank packing and both tensor index formulae.
def pair_indices(mask):
 ranks=[];n=0
 for valid in mask:
  n+=valid;ranks.append(max(0,n-1))
 packed=[0]*10
 for pos,(rank,valid) in enumerate(zip(ranks,mask)):packed[rank]+=pos*valid
 even=n-n%2
 adjacent=[];separated=[]
 for rank,valid in zip(ranks,mask):
  paired=valid and rank<even
  a=rank+1-2*(rank%2) if paired else rank
  b=(rank+even//2)%max(even,1) if paired else rank
  assert 0<=a<10 and 0<=b<10
  adjacent.append(packed[a]);separated.append(packed[b])
 return adjacent,separated

def average(vals,mask,partners,nonlinear=True):
 n=sum(mask)
 if not n:return 0.0
 return sum((math.tanh if nonlinear else float)(0.5*vals[j]+0.5*vals[partners[j]]) for j in range(10) if mask[j])/n
cases=0
for mask in itertools.product((0,1),repeat=10):
 a,b=pair_indices(mask);valid=[j for j,x in enumerate(mask) if x];n=len(valid)
 for partner in [a,b]:
  for j in valid:
   assert mask[partner[j]] and partner[partner[j]]==j
  assert sorted(partner[j] for j in valid)==valid
  assert [j for j in valid if partner[j]==j]==(valid[-1:] if n%2 else [])
 if n<=3:assert [a[j] for j in valid]==[b[j] for j in valid]
 for vals in [[(-1.0)**j*(j+1)/4 for j in range(10)],[0.0]*10,[2.5]*10,[(-1.0)**j*1e100 for j in range(10)]]:
  expected=sum(vals[j] for j in valid)/max(n,1)
  for partner in [a,b]:
   linear=average(vals,mask,partner,False)
   assert math.isclose(linear,expected,rel_tol=1e-12,abs_tol=1e-12*max(1,abs(expected)))
   result=average(vals,mask,partner);assert math.isfinite(result)
   dirty=[x if mask[j] else float('nan') for j,x in enumerate(vals)]
   assert result==average(dirty,mask,partner)
   if len(set(vals[j] for j in valid))<=1:
    original=sum(math.tanh(vals[j]) for j in valid)/max(n,1)
    assert math.isclose(result,original,rel_tol=1e-12,abs_tol=1e-12)
   cases+=1
mask=[1]*4+[0]*6;a,b=pair_indices(mask);vals=[2.0,2.0,-2.0,-2.0]+[0.0]*6
assert abs(average(vals,mask,a)-average(vals,mask,b))<1e-12 # signed symmetric sums can cancel
vals=[3.0,3.0,-1.0,-1.0]+[0.0]*6
assert abs(average(vals,mask,a)-average(vals,mask,b))>0.1
# Verify source identities for every authorized frozen ancestor against registry.
w=json.load(open('/workspace/workspace.json'))
for ancestor in w['available_ancestor_sources']:
 assert hashlib.sha256((root/ancestor['file']).read_bytes()).hexdigest()==ancestor['source_sha256'],ancestor['file']
assert hashlib.sha256((root/'baseline_reference.py').read_bytes()).hexdigest()=='f4b473cbacf60d72cff90f3721ad754dd617ee6065fe3fca2fc9cd4be2b25c36'
print(json.dumps(dict(schema='passed full resolved study schema',variants='4 compiled; CONFIG/defaults and declared-factor AST parity passed',inherited='all other methods and learned module constructor expressions/order preserved; all frozen source digests verified',mathematics=dict(support_masks=1024,scalar_cases=cases,properties=['bounded occupied indices','involution and multiplicity','same newest singleton','pre-tanh mean preservation','invalid-slot exclusion','M<=3 equality','homogeneous identity','heterogeneous pairing distinction']),source_sha256=digests,native_tensor_checks='not available; PyTorch absent; no training or scoring executed'),indent=2))
Path('/tmp/pairing_checks.json').write_text(json.dumps(dict(support_masks=1024,scalar_cases=cases,source_sha256=digests)))
